@startuml

class Center {
  + Name : string
  + Address : string
}

class Room {
  + Number : int
  + Capacity : int
}

class Person {
  + FirstName : string
  + FamilyName : string
  + BirthDate : date
}

class Trainer extends Person {
  + Diploma : string
}

class Session {
  + Date : date
  + StartHour : time
}

class GroupSession extends Session {
  + Type : string
}

class IndividualSession extends Session {}

class Participation {
}

Center "1" *-- "1..*" Room
Center "1" -- "0..*" Session
Room "1" -- "0..*" Session

Person "1" -- "0..*" Participation
Participation "*" -- "1" Session

Trainer "1" -- "0..*" GroupSession : supervises

@enduml

